import java.util.Scanner;

public class Main {
    public static long readInput(Scanner sc) {
        long result = 0;
        while (true) {
            if (!sc.hasNext()) break;
            String token = sc.next();
            if (token.matches("\\d+")) {
                result = Long.parseLong(token);
                break;
            }
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x = readInput(sc);
        long y = readInput(sc);
        long n = readInput(sc);

        long a = 0, b = 1;
        for (long i = 1; i <= n; ++i) {
            long p = x * i / y;
            long q = p + 1;
            long temp = i * Math.abs(x * b - a * y);
            long t1 = b * Math.abs(x * i - y * p);
            long t2 = b * Math.abs(x * i - y * q);
            if (t1 < temp) {
                a = p;
                b = i;
                temp = t1;
            }
            if (t2 < temp) {
                a = q;
                b = i;
                temp = t2;
            }
        }
        System.out.println(a + "/" + b);
        sc.close();
    }
}
